(() => {
'use strict';
const trip=window.TRIP;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const maps=p=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.query||p.name+' Medellin');
const directions=(p,origin=trip.hotel)=>'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(origin.query)+'&destination='+encodeURIComponent(p.query||p.name+' Medellin')+'&travelmode=driving';
const restaurant=id=>trip.restaurants.find(r=>r.id===id);
const sorted=rs=>[...rs].sort((a,b)=>(b.rating??-1)-(a.rating??-1)||(b.reviews??0)-(a.reviews??0));
let activeMap=null;
let selected=13;

function nightCard(r,primary,index){return `<article class="night-option"><div class="score">${r.rating?`${index+1}. ★ ${r.rating.toFixed(1)}/5 · ${r.reviews.toLocaleString('es-CO')} reseñas`:'ELECCIÓN PERSONAL · SIN NOTA COMPARABLE'}</div><h4>${esc(r.name)}${primary===r.id?' <span class="choice">Cena elegida</span>':''}</h4><p>${esc(r.kind)}<br>${esc(r.zone)}</p><p>${esc(r.hours)}</p>${external(directions(r),'Desde el hotel ↗')}${external(r.url||maps(r),r.url?'Consultar / reservar ↗':'Ver lugar ↗')}</article>`}

function dayRoute(day){
 if(day.id===13)return directions(trip.hotel,trip.places.airport);
 const ps=day.route.map(id=>trip.places[id]);
 if(ps.length===1)return directions(ps[0]);
 return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(trip.hotel.query)+'&destination='+encodeURIComponent(ps.at(-1).query)+'&waypoints='+encodeURIComponent(ps.slice(0,-1).map(p=>p.query).join('|'))+'&travelmode=driving';
}

function renderMap(day){
 const entries=[{...trip.hotel,kind:'hotel',label:'H'},...day.places.map((id,i)=>({...trip.places[id],kind:'visit',label:String(i+1)})),...sorted(day.dinners.map(restaurant)).filter(r=>Number.isFinite(r.lat)).map((r,i)=>({...r,kind:'dinner',label:r.id===day.primary?'★':'C'+(i+1)}))];
 $('#map-points').innerHTML=entries.map(p=>external(p.kind==='hotel'?maps(p):directions(p),esc(p.label+' · '+p.name))).join('');
 if(!window.L){$('#day-map').innerHTML='<div class="map-fallback">El mapa no pudo cargar. Los enlaces de cada lugar y de la ruta siguen disponibles debajo.</div>';return;}
 activeMap=L.map('day-map',{scrollWheelZoom:false}).setView([trip.hotel.lat,trip.hotel.lng],13);
 let failures=0;
 const tile=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'});
 tile.on('tileerror',()=>{if(++failures===3)$('#map-state').textContent='El fondo cartográfico no está cargando. Usa los enlaces de ubicación.'});
 tile.addTo(activeMap);
 const bounds=L.latLngBounds(entries.map(p=>[p.lat,p.lng]));
 entries.forEach(p=>{
  const km=activeMap.distance([trip.hotel.lat,trip.hotel.lng],[p.lat,p.lng])/1000;
  const marker=L.marker([p.lat,p.lng],{title:p.name,icon:L.divIcon({className:'pin '+p.kind,html:esc(p.label),iconSize:[32,32],iconAnchor:[16,16]})}).addTo(activeMap);
  marker.bindPopup(`<strong>${esc(p.name)}</strong><br>${p.address?esc(p.address)+'<br>':''}${p.kind==='hotel'?'Su punto de partida':km.toFixed(1)+' km del hotel en línea recta (aprox.)'}<br>${external(directions(p),'Abrir trayecto ↗')}`);
 });
 const fit=()=>activeMap.fitBounds(bounds,{padding:[35,35],maxZoom:15});
 fit();L.control.scale({imperial:false}).addTo(activeMap);
 $('#reset-map').onclick=fit;
}

function renderDay(id,focus=false){
 const day=trip.days.find(d=>d.id===Number(id))||trip.days[0];selected=day.id;
 if(activeMap){activeMap.remove();activeMap=null;}
 document.querySelectorAll('.day-tab').forEach(b=>{const yes=Number(b.dataset.day)===day.id;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});
 $('#day-content').setAttribute('aria-labelledby','tab-'+day.id);
 const guatape=day.id===19;
 const weatherSource=trip.sources[guatape?15:14][1];
 $('#day-content').innerHTML=`<div class="day-head"><div><div class="eyebrow">${esc(day.day).toUpperCase()} ${day.id} · OCTUBRE 2026</div><h3>${esc(day.title)}</h3><p>${esc(day.subtitle)}</p></div><span class="badge">${esc(day.pace)}</span></div>
 <div class="day-layout"><div><div class="timeline"><div class="timeline-heading">SU DÍA, PASO A PASO</div>${day.stops.map(s=>{const p=s.place?trip.places[s.place]:s.restaurant?restaurant(s.restaurant):null;return `<article class="stop"><div class="time">${esc(s.time)}</div><div class="stop-content"><h4>${esc(s.title)}</h4><p>${esc(s.text)}</p>${s.detail?`<p class="detail">${esc(s.detail)}</p>`:''}${p?external(day.id===13&&s.place==='airport'?directions(trip.hotel,p):directions(p),day.id===13&&s.place==='airport'?'Del aeropuerto al hotel ↗':'Desde el hotel ↗')+(p.url?' &nbsp; '+external(p.url,'Información oficial ↗'):''):''}</div></article>`}).join('')}</div>
 <div class="rain-plan"><strong>Si llueve · Plan alternativo</strong><p>${esc(day.rain)}</p></div>${day.extra?`<details class="day-extra"><summary>Otros miradores para intercambiar este jueves</summary><p>${esc(day.extra)}</p>${(day.optionalPlaces||[]).map(id=>external(directions(trip.places[id]),esc(trip.places[id].name)+' ↗')).join('<br>')}</details>`:''}</div>
 <aside class="day-sidebar"><div class="map-card"><div class="map-heading"><strong>Mapa del ${day.id} de octubre</strong><button id="reset-map" type="button" aria-label="Mostrar todos los lugares del día">Ver todos</button></div><div class="map" id="day-map" role="region" aria-label="Mapa del día ${day.id} con hotel, atracciones y cenas"></div><div class="map-legend"><span class="key hotel">H · Su hotel</span><span class="key">1–${day.places.length} · Visitas</span>${day.dinners.length?'<span class="key dinner">C · Cenas / ★ elegida</span>':''}</div><div class="map-note" id="map-state">Puntos de orientación aproximados. El hotel siempre aparece. Abre cada lugar para navegar; no se dibuja una ruta vial.</div><div class="map-points" id="map-points"></div><a class="route-link" href="${esc(dayRoute(day))}" target="_blank" rel="noopener noreferrer">${day.id===13?'Abrir traslado MDE → Hampton ↗':day.id===20?'Abrir traslado Hampton → MDE ↗':'Abrir trayecto diurno desde el hotel ↗'}</a></div>
 <div class="weather"><div class="weather-top"><span>☂ ${guatape?'GUATAPÉ':'MEDELLÍN'} · ${day.id} OCT</span><span>CLIMA HISTÓRICO</span></div><div class="weather-numbers"><div><strong>${guatape?'57–72':'63–77'}°F</strong><span>Mínima y máxima típicas</span></div><div><strong>≈${guatape?'80':'85'}%</strong><span>Referencia de día con lluvia</span></div></div><p>Referencia de octubre, no pronóstico para 2026.</p>${external(weatherSource,'Fuente y clima mensual ↗')} · <a href="#clima-metodo">Cómo interpretarlo</a></div>${guatape?'<figure class="destination-photo"><img src="assets/guatape.jpg" alt="El embalse de Guatapé visto desde la Piedra del Peñol" loading="lazy"><figcaption>El embalse desde la cima. El ascenso es opcional.</figcaption></figure>':''}</aside></div>
 <section class="night"><div class="eyebrow">AL CAER LA NOCHE</div><h3>${esc(day.nightTitle)}</h3><p>${esc(day.nightText)}</p>${day.dinners.length?`<div class="night-options">${sorted(day.dinners.map(restaurant)).map((r,i)=>nightCard(r,day.primary,i)).join('')}</div><p class="night-note">Puntuaciones y reseñas reproducidas de la guía del 10/09/2026, sin actualización en vivo. Orden: mayor nota, luego más reseñas. <a href="#criterio-ranking">Ver criterio</a>.</p>`:''}</section><p class="timing-note">Los vuelos del 13 a las 18:25 y del 20 a las 11:00 fueron indicados por ustedes y se asumen en hora de Colombia (una hora menos que Puerto Rico). Los demás horarios son propuestas; * indica estimación sujeta a trámites y tráfico. Esta guía no confirma reservas.</p>`;
 renderMap(day);
 if(focus)$('#tab-'+day.id).focus();
}

$('#day-tabs').innerHTML=trip.days.map(d=>`<button type="button" id="tab-${d.id}" class="day-tab" role="tab" aria-controls="day-content" aria-selected="false" tabindex="-1" data-day="${d.id}"><span>${d.abbr}</span><strong>${d.id}</strong><small>${esc(d.short)}</small></button>`).join('');
$('#day-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(!b)return;history.replaceState(null,'','#dia-'+b.dataset.day);renderDay(b.dataset.day);});
$('#day-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=trip.days.findIndex(d=>d.id===selected);const n=e.key==='Home'?0:e.key==='End'?7:(index+(e.key==='ArrowRight'?1:7))%8;history.replaceState(null,'','#dia-'+trip.days[n].id);renderDay(trip.days[n].id,true);});
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#dia-(1[3-9]|20)$/);if(m)renderDay(Number(m[1]));});

$('#restaurant-list').innerHTML=`<p id="criterio-ranking" class="ranking-note"><strong>Qué significa el ranking:</strong> orden descendente de las notas de su guía consolidada del 10 de septiembre de 2026; empates por cantidad de reseñas. Es una selección que mezcla restaurantes y rooftops, no un ranking oficial de toda Medellín. La plataforma original no está documentada en los PDF, por eso no se presenta como Google ni Tripadvisor. Las notas no se han verificado en vivo. La cena elegida responde también al estilo, cercanía y día de apertura.</p><div class="restaurant-grid">${sorted(trip.restaurants).map((r,i)=>`<article class="restaurant"><div class="rank">${r.rating?'N.º '+String(i+1).padStart(2,'0')+' DE LA SELECCIÓN':'ANIVERSARIO · ELECCIÓN PERSONAL'}</div><h3>${esc(r.name)}</h3><div class="rating">${r.rating?'★ '+r.rating.toFixed(1)+' <span class="meta">/ 5 · '+r.reviews.toLocaleString('es-CO')+' reseñas</span>':'Sin puntuación comparable'}</div><p><strong>${esc(r.zone)}</strong><br>${esc(r.kind)}</p><p>${esc(r.why)}</p><p>${esc(r.hours)}</p>${external(directions(r),'Desde el Hampton ↗')} &nbsp; ${external(r.url||maps(r),r.url?'Consultar ↗':'Ver lugar ↗')}</article>`).join('')}</div>`;

$('#practical').innerHTML=`<div class="practical-grid"><article><h3>Las reservas prioritarias</h3><ul><li><strong>Viernes 16 · Andrés:</strong> 19:00–19:30. Anotar aniversario y pedir mesa lejos de parlantes.</li><li><strong>Miércoles 14 · Carmen:</strong> 19:30. Confirmar carta o degustación, duración y restricciones alimentarias.</li><li><strong>Jueves 15 · Colosal:</strong> mesa cubierta con vista desde las 17:00.</li><li><strong>Sábado 17 · Comuna 13:</strong> guía local, ruta corta y recogida a las 08:00.</li><li><strong>Lunes 19 · Guatapé:</strong> excursión privada con paradas y precio total por escrito.</li><li><strong>OCI y Explora:</strong> confirmar mesa del sábado y tarifa de entrada para extranjeros del domingo.</li></ul></article><article><h3>Moverse con comodidad</h3><ul><li>Pedir vehículo desde hotel o aplicación. Verificar placa y conductor; esperar dentro hasta que llegue.</li><li>Los tiempos de la guía son márgenes de planificación, sin tráfico en vivo. Los cruces, pendientes y lluvia importan más que la distancia.</li><li>Para miradores y Guatapé, acordar el transporte de vuelta antes de salir.</li><li>Para excursiones, verificar el Registro Nacional de Turismo del operador y qué incluye cada tarifa.</li><li>Para fotografiar, una cámara pequeña es suficiente. Pedir permiso para retratos y seguir las reglas de cada museo.</li><li>La guía mantiene descansos y caminatas cortas. Informar al guía de cualquier necesidad de movilidad.</li></ul></article><article><h3>Maleta y gastos</h3><ul><li>Paraguas compacto, capa ligera, calzado con agarre y chaqueta fina para la noche.</li><li>Agua, protector solar, batería externa y paño para los lentes.</li><li>Precios en pesos colombianos (COP). Consultar menú y total al reservar; no se presentan presupuestos como cotizaciones.</li><li>Llevar identificación para consultar descuentos. Ser mayor de 60 no garantiza la misma tarifa en todos los museos.</li><li>Colombia tiene una hora menos que Puerto Rico durante el viaje.</li><li>Vuelos indicados por ustedes: llegada el 13 a las 18:25 y salida el 20 a las 11:00, asumidos en hora de Colombia. Coordinar el traslado del martes a las 06:30. Las reservas de servicios no están verificadas en esta guía.</li></ul></article></div>
<details class="climate-details" id="clima-metodo" open><summary>Cómo leer la temperatura y la lluvia de cada día</summary><p>Se usa la climatología mensual de Weather Spark: Medellín ronda 63 °F de mínima y 77 °F de máxima en octubre; Guatapé, 57–72 °F. Las temperaturas de referencia se convirtieron a Fahrenheit y se redondearon al grado entero. Día húmedo significa al menos unos 1 mm de precipitación. El porcentaje expresa frecuencia histórica de días con lluvia; no duración ni intensidad. Se redondea a ≈85% en Medellín y ≈80% en Guatapé. Repetir la referencia mensual evita inventar diferencias entre fechas. Consultar el pronóstico local 5–7 días antes y revisarlo cada mañana. Los miradores de ladera pueden ser más frescos que el valle.</p></details>`;

$('#sources').innerHTML=`<p>Revisión de fuentes: 10 de septiembre de 2026, hora de Puerto Rico. Base: <em>Guía Medellín Rafy + Vanessa, octubre 2026</em> y <em>Guía visual Medellín Rafy y Vanessa 2026-2</em>, facilitadas por ustedes. Se reorganizan sus recomendaciones y se contrastan horarios principales en las páginas de cada lugar. Los enlaces permiten reconfirmar antes del viaje.</p><ul>${trip.sources.map(([label,url])=>'<li>'+external(url,esc(label))+'</li>').join('')}</ul><p><strong>Ajuste de calendario:</strong> la Fiesta del Libro es del 11 al 20 de septiembre de 2026 y no coincide con este viaje. Los eventos de octubre mencionados en los PDF que no se han confirmado nuevamente no se incluyen como compromisos del itinerario.</p><p><strong>Mapas:</strong> cartografía © OpenStreetMap; marcadores de orientación, no levantamiento de accesos. Coordenadas del Hampton y Colosal contrastadas con fichas públicas de Waze; los demás puntos son aproximados. Los enlaces de navegación buscan el nombre y la dirección del establecimiento para seleccionar el acceso correcto. Las alternativas de miradores se abren por su nombre para evitar fijar un acceso no confirmado.</p><p><strong>Fotografías:</strong> Medellín: ${external('https://commons.wikimedia.org/wiki/File:Medell%C3%ADn_Panor%C3%A1mica.jpg','Carlos Andres Granada')} · ${external('https://creativecommons.org/licenses/by-sa/4.0/','CC BY-SA 4.0')}. Guatapé: ${external('https://commons.wikimedia.org/wiki/File:Guatape_(98321797).jpeg','David Carlson')} · ${external('https://creativecommons.org/licenses/by-sa/3.0/','CC BY-SA 3.0')}. Encuadres recortados en pantalla; las fotografías mantienen su licencia original.</p>`;
const initial=location.hash.match(/^#dia-(1[3-9]|20)$/);renderDay(initial?Number(initial[1]):13);
})();
